const $=s=>document.querySelector(s), e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), money=x=>Number(x).toLocaleString('ko-KR')+'원', enc=encodeURIComponent;
let cfg,me,route='education',chatSession=null,chatMessages=[],threadId=null,files=[],estimate=null,fields=null,selectedDate=null,calendarMonth=new Date(),selectedPlan='lite',selectedAdd=new Set(),pub=null,renderId=0,publicMode=location.pathname.startsWith('/c/')||location.pathname.startsWith('/widget/'),slug=location.pathname.split('/')[2];
const btn=(text,fn,cls='')=>`<button class="${cls}" onclick="${fn}">${e(text)}</button>`, card=(title,body)=>`<section class="card"><h2>${e(title)}</h2>${body}</section>`, label=(text,body)=>`<label class="label">${e(text)}</label>${body}`, input=(id,v='',type='text',ph='')=>`<input id="${id}" type="${type}" value="${e(v)}" placeholder="${e(ph)}">`, ta=(id,v='')=>`<textarea id="${id}">${e(v)}</textarea>`, select=(id,opts,v)=>`<select id="${id}">${opts.map(([k,n])=>`<option value="${e(k)}" ${k===v?'selected':''}>${e(n)}</option>`).join('')}</select>`, pageTop=(h,s)=>`<div class="top"><div><h1>${e(h)}</h1><p class="muted">${e(s)}</p></div><span class="tag">${cfg.demo?'로컬 개발 환경':'연동 검증 환경'}</span></div>`, has=k=>me?.entitlements.includes(k), go=p=>location.hash=p, val=id=>$('#'+id).value, checked=id=>$('#'+id).checked;
const names={agents:'AI 상담원 관리',inbox:'상담 목록',preview:'채팅창 미리보기',education:'AI 교육시키기',calendar:'일정표 보기',customers:'고객·업무 관리',channels:'외부 채널 연동',alerts:'알림',settings:'설정',pricing:'요금제 및 결제'}, states={open:'진행 중',pending:'승인 대기',pending_payment:'결제 확인 대기',confirmed:'확정',cancelled:'취소',completed:'완료',resolved:'처리 완료',draft:'작성 중'};
async function api(path,body,method){let r=await fetch(path,{method:method||(body===undefined?'GET':'POST'),headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});if(r.status===204)return {};let x=await r.json().catch(()=>({detail:'서버 응답 오류'}));if(!r.ok){let err=new Error(typeof x.detail==='string'?x.detail:JSON.stringify(x.detail));err.status=r.status;throw err}return x}
function toast(text){document.querySelector('.toast')?.remove();let d=document.createElement('div');d.className='toast';d.textContent=text;document.body.append(d);setTimeout(()=>d.remove(),3500)}
function modal(title,html){$('.modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal" onclick="if(event.target===this)this.remove()"><div class="card"><h2>${e(title)}</h2>${html}<div style="margin-top:12px">${btn('닫기',"this.closest('.modal').remove()")}</div></div></div>`)}
