/* v0.5: direct examples are a real training job, never an immediate free knowledge write. */
const v05Api=api;
api=async function(path,body,method){
  let result=await v05Api(path,body,method);
  if(path==='/api/faq'&&result?.requires_run){
    if(!result.enough)throw Error('교육 크레딧이 부족합니다. 교육 크레딧을 충전한 뒤 다시 시도하세요.');
    if(!confirm(`교육 견적은 최대 ${result.maxCredits}C입니다. 크레딧을 예약하고 교육을 시작할까요?`))return {ok:true,estimated:true};
    await v05Api('/api/training/'+result.id+'/run',{});
    return {ok:true,trained:true,review_required:true};
  }
  return result;
};
